window.GOHUD_SEARCH=window.GOHUD_SEARCH||{};
window.GOHUD_SEARCH["ru"]={"p":["index.html","install.html","ai.html","widgets.html","widgets-surfaces.html","widgets-messages.html","widgets-hud.html","widgets-feedback.html","widgets-forms.html","widgets-shapes.html","widgets-overlays.html","widgets-style.html","theming.html","theming-presets.html","theming-tokens.html","theming-opacity.html","theming-skins.html","theming-own.html","theming-contrast.html"],"n":["Обзор","Установка","Go HUD Skill","Виджеты","Widgets-Surfaces","Widgets-Messages","Widgets-Hud","Widgets-Feedback","Widgets-Forms","Widgets-Shapes","Widgets-Overlays","Widgets-Style","Темы","Theming-Presets","Theming-Tokens","Theming-Opacity","Theming-Skins","Theming-Own","Theming-Contrast"],"d":[[0,"showcase","Как это выглядит в игре",0,"Средневековый и sci-fi пресеты — лист персонажа, инвентарь и задания; формы, сетки и карточки вопросов; угловатые панели и сенсорное управление. Пресет переключается одной строкой кода. Средневековье — персонаж, инвентарь и задания Средневековье — формы, сетки и карточки вопросов Sci-fi — угловатые панели и сенсорное управление Все шесть пресетов и как их переключать →","",-1],[0,"what","Что он берёт на себя",0,"Больше всего времени в игровом интерфейсе съедает не форма кнопки, а всё то, что расходится между устройствами. gohud держит это расхождение в одном месте. Каждый размер — это токен Отступы, углы и размеры текста вызываются по имени, а не пишутся числами. Смените тему — и весь экран поедет вместе с ней. Видимый размер ≠ размер нажатия Кнопка закрытия выглядит на 36dp, но её область нажатия — 48dp. Там, где тесно стоящие слоты перекрываются, нажатие получает тот, чей центр ближе. Вырезы и клавиатуры Элементы HUD остаются внутри безопасной области, а поле ввода поднимается над виртуальной клавиатурой, когда та появляется. «Назад» закрывает одно Escape и кнопка «Назад» на Android закрывают только самую верхнюю поверхность. Стопка окон не исчезает целиком. Уведомления не перехватывают ввод Нажмите сквозь снекбар — и кнопка под ним его получит. Фокус тоже не отбирается. Иконки запрашиваются по имени Виджеты знают только GoIconSet.CLOSE. Смените набор — и все рисунки поменяются, не тронув ни строки кода. Шесть образов, одна строка GoUi.use_preset() меняет тему, скин и иконки разом — скруглённые, срезанные sci-fi или кованые средневековые рамки. Читаемость — по измерению Каждая тема проверена по WCAG, включая состояния кнопок и полупрозрачные панели HUD поверх чисто белого и чисто чёрного. Всё работает и без включения плагина. Включение добавляет автозагрузку GoRuntime, которая следит за размером окна, масштабом dp и высотой клавиатуры, плюс настройки проекта для ресурса конфигурации и пресета — это удобства, а не требования.","",-1],[0,"install","Установка gohud",0,"Два пути. Поручите ИИ-агенту или положите папку в проект — больше настраивать нечего. Установка","",-1],[0,"start","Быстрый старт",0,"Пять строк выводят экран с темой. Полное прохождение — на странице установки. Быстрый старт","",-1],[0,"presets","Смена внешнего вида — цвета и форма",0,"Theme может перерисовать только то, что рисует движок. Скруглённые углы — единственные, какие есть у StyleBoxFlat, а стик, быстрые слоты и обучающая подсказка рисуются кодом, поэтому одна лишь тема никогда не изменит их форму. Поэтому в gohud есть пресеты: тема, скин и набор иконок, выбранные как одно целое. Пресет Вид default_dark Исходный gohud — скруглённые углы, мягкий синий акцент default_light Те же формы на светлой палитре scifi_dark Срезанные углы, неоновые голубые грани и свечение, шестиугольный стик, прицельные скобки scifi_light Те же угловатые формы в яркой «чертёжной» палитре medieval_dark Тёмное железо и кожа, рамки под старое золото, заклёпки, гравированные иконки, заголовки шрифтом Cinzel medieval_light Пергамент, чернила и бронза с теми же коваными рамками default_dark — скруглённые углы, мягкий синий акцент default_light — те же формы, светлая палитра scifi_dark — срезанные углы, голубой неон scifi_light — те же угловатые формы, «чертёжная» палитра Все четыре — это один и тот же экран галереи. Не отличается ни строки кода, только имя пресета. Углы кнопок, формы переключателей, строки списка и рамки полей ввода едут вместе.","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # тема, скин и иконки разом",-1],[0,"medieval-collection","Средневековая коллекция",1,"medieval_dark соединяет железо и кожу со старым золотом; medieval_light берёт пергамент и чернила. На рамках меню есть заклёпка и небольшой угловой орнамент, а всегда видимый HUD остаётся сдержанным; 16 гравированных иконок перерисовывают названия предметов, и только заголовки и подзаголовки используют встроенный шрифт Cinzel. medieval_dark — железо и кожа medieval_light — пергамент и чернила Оба снимка — это examples/medieval/medieval.tscn, собранный из стандартных виджетов. Руководство по средневековью и как сделать своё королевство →","",4],[0,"the-same-screen-on-a-phone-and-on-a-desktop","Один и тот же экран на телефоне и на настольном компьютере",1,"Снимки галереи сделаны на телефоне в книжной ориентации. Ниже — тот же код при 1280×800: содержимое останавливается на читаемой ширине (480dp) и центрируется, а HUD остаётся по углам. Форма обходит плавающие элементы HUD, но не двигается, если и так их не задевает: сдвиг ради сдвига увёл бы содержимое с центра широкого экрана. default_dark · 1280×800 scifi_dark · 1280×800","",4],[0,"the-same-sheet-a-different-look","Тот же лист, другой вид",1,"Обычный — скруглённая карточка, закреплённый ряд поиска и подвал Sci-fi — акцентная грань сверху, срезанные углы, свечение Выберите пресет в Project Settings → gohud → Theme → Preset или задайте GoConfig.preset. Явно заполненные theme, skin или icons берут верх над пресетом, так что можно взять пресет и переопределить лишь одно из трёх. Новая тема — это один файл JSON. new_theme.py kingdom --from medieval_dark пишет палитру, в которой расписано каждое унаследованное значение; make_theme.py kingdom собирает тему, графику элементов управления и регуляторы скина, после чего пресет появляется в списке выбора. Все настройки и регуляторы →","",4],[0,"skin","Скины — там, куда Theme не дотягивается",0,"Скину принадлежат стик, лицевые панели быстрых слотов, кольцо обучающей подсказки, чипы, скелетоны, оповещения, разделители и заголовки секций. Наследуйте его и переопределяйте только то, что хотите изменить. Класс Какие формы умеет GoStyleBoxCut Диагонально срезанные углы (фаска), одна утолщённая акцентная грань, внешнее свечение GoStyleBoxBracket Только угловые метки, без замыкания содержимого в рамку GoStyleBoxMedieval Кованая рамка с заклёпками, угловой гравировкой, фасочным бликом и фактурой материала Все три сериализуются в ресурс Theme — именно это и позволяет теме менять форму, а не только цвет. GoSkinSciFi и GoSkinMedieval — подклассы, идущие в комплекте. GoStyle.box() всегда возвращает StyleBoxFlat, потому что вызывающий код получает его и правит bg_color или corner_radius. Если нестандартная форма должна уцелеть, используйте GoStyle.surface().","class_name MySkin extends GoSkin func slot_box(accent: Color, lit: bool) -> StyleBox: var box := GoStyleBoxCut.new() box.bg_color = accent box.cut = 6.0 box.edge_color = accent return box",-1],[0,"widgets","Виджеты",0,"Все части в одной таблице. Каждая подробно → Класс Базовый Что делает GoSurface Control Оболочка плавающей карточки — размещение по центру, снизу или у элемента, закреплённые шапка и подвал, прокручиваемое тело, изменение размера перетаскиванием GoSheet CanvasLayer Страницы, поднимающиеся снизу, на собственном слое, поэтому они лежат поверх HUD GoDialogs Node Подтверждения и оповещения, которые можно await; destructive — для необратимых действий GoForm MarginContainer Формы с ограниченной шириной, обходящие виртуальную клавиатуру и, с avoid_hud, сам HUD GoScroll ScrollContainer Сенсорная прокрутка; полоса прокрутки прячется во внутренние отступы карточки GoNotice PanelContainer Снекбар, который не берёт ни ввод, ни фокус GoPromptCard PanelContainer Вопрос, который не блокирует игру GoCoachMark Control Обучающий тур, указывающий на настоящие элементы управления; нажатие на цель двигает тур дальше GoHudAnchor Control Прикрепляет элементы HUD к одной из девяти точек безопасной области GoBar Control Полосы здоровья, маны и опыта с плавным изменением GoSlot Button Быстрый слот — иконка, количество, перезарядка и горячая клавиша на одной лицевой панели GoJoystick Control Виртуальный стик в фиксированном, следящем или относительном режиме GoIconButton Button Выглядит маленькой, нажимается большой GoStyle статический Кнопки, строки списка, поля ввода, чипы, таблицы, вкладки и прочее, сделанные единым образом","",-1],[0,"waiting-telling-counting","Ожидание, сообщения, счётчики",1,"Класс Базовый Что делает GoSnackbar Node сообщение, которое само встаёт на место GoSpinner Control ожидание без видимого конца GoBadge PanelContainer точка непрочитанного, метка НОВОЕ, 99+","",9],[0,"forms-and-lists","Формы и списки",1,"Класс Базовый Что делает GoField VBoxContainer строка, которая может быть неверной GoInputGroup HBoxContainer поле ввода, сваренное со своей кнопкой GoCombobox Button выбор с поиском GoCodeInput VBoxContainer купоны и подарочные коды GoTable VBoxContainer сортируемые заголовки, выбираемые строки GoPagination HBoxContainer страницы или строка «Ещё»","",9],[0,"shapes-games-actually-use","Формы, которые играм действительно нужны",1,"Класс Базовый Что делает GoRewardCalendar VBoxContainer ежедневный вход GoRadar · GoDonut Control характеристики с одного взгляда GoCarousel VBoxContainer баннеры и выбор персонажа GoKbd HBoxContainer подсказки клавиш, которые не врут","",9],[0,"over-the-screen","Поверх экрана",1,"Класс Базовый Что делает GoDrawer CanvasLayer боковая панель GoPopover RefCounted карточка с привязкой GoContextMenu RefCounted долгое нажатие и правый клик GoConsole CanvasLayer консоль разработчика","",9],[0,"ai","Go HUD Skill",0,"В gohud входит ИИ-навык: весь API, готовые шаблоны и запуск предпросмотра. Вставьте один блок в своего агента — он установит gohud и будет знать, как им пользоваться. Go HUD Skill","",-1],[0,"readable","Читаемость измеряют, а не прикидывают на глаз",0,"«Красиво» — дело вкуса; «читаемо» можно измерить. Бледно-серый текст отлично смотрится на хорошем мониторе и исчезает на телефоне при дневном свете — выбор на глаз рано или поздно приводит именно к этому. Каждая пара цветов и подпись каждого состояния кнопки поверх панели, на которой она лежит, измеряется по WCAG во всех шести темах. Полупрозрачные цвета сначала накладываются на настоящий фон — если измерять их напрямую, коэффициент получается лучше, чем на экране. Поэтому цвета текста выводятся, а не выбираются: сборщик берёт значение из палитры как отправную точку и поднимает его светлоту, пока оно не пройдёт порог на всех поверхностях, где может оказаться. Измените палитру — и контраст пойдёт следом. Правила и ловушки за ними → Проверки, релизы и этот сайт Одна точка входа запускает все проверки; каждая часть видит то, чего не видят остальные. Проверка Что ловит run_tests.sh на четырёх размерах экрана Поведение и раскладку виджетов, позиции в RTL, фокус с клавиатуры, контраст скина во время работы, все пресеты new_project_check.sh Скрытые зависимости от проекта-хозяина; с --zip — релиз в том виде, в каком он поставляется, с --export — сборку для Web check_contrast.py Контраст по WCAG в каждом файле темы, включая состояния кнопок и полупрозрачные панели check_generated.py · check_scaffold.sh Сгенерированные темы совпадают со своими палитрами; одноразовая тема собирается и проходит проверку контраста check_package.py Версия из package.json, перенос записей в журнале изменений и содержимое ZIP — во временных копиях check_site.py Ссылки этого сайта, якоря, язык страницы, глоссарий и таблицы регуляторов Последний записанный прогон — 2026-09-13, Godot 4.7.2, macOS, рендерер Compatibility. 438 из 438 проверок на 390×844, 844×390, 768×1024 и 1280×800 в пустом проекте; снова 438 из 438 с автозагрузкой GoRuntime; экспорт для Web; ноль провалов по контрасту в шести темах. Godot 4.6 и физические устройства на Android или iOS в этот прогон не входили.","python3 addons/gohud/tools/check_contrast.py bash addons/gohud/tools/check_all.sh",-1],[0,"release-versions","Версии релизов",1,"Версия — та, что записана в package.json: упаковка её никогда не повышает. Чтобы выпустить новую версию, сначала измените это число. Успешный прогон выставляет это значение в plugin.cfg и GoUi.VERSION, а при первой упаковке этой версии переносит заметки из раздела Unreleased в CHANGELOG.md в датированную запись. Повторная упаковка той же версии заново собирает её ZIP и заменяет прежний. Неудачный прогон не меняет ничего. В ZIP не попадают этот сайт, тесты, инструменты и package.json.","cat addons/gohud/package.json # { \"version\": \"1.1.0\" } bash addons/gohud/tools/package.sh # 1.1.0 → builds/1.1.0/gohud-1.1.0.zip",15],[0,"this-site","Этот сайт",1,"Страницы — это обычный HTML в www/: английский в корне, корейский в ko/. Рабочий процесс GitHub Actions публикует эту папку как корень сайта.","python3 addons/gohud/tools/make_site.py # глоссарий и таблицы регуляторов скина, порождённые из исходников python3 addons/gohud/tools/check_site.py # ссылки, якоря, язык, глоссарий, порождённые таблицы bash addons/gohud/tools/site_shots.sh /tmp/shots # снимки каждой страницы для настольного экрана и телефона",15],[1,"ai-first","Самый быстрый путь — поручите установку ИИ-агенту",0,"Один блок текста, вставленный в Claude Code, Codex, Cursor или Gemini CLI, установит и навык, и дополнение, а потом объяснит вам gohud. На этом пути ничего ниже этой карточки не нужно. Открыть страницу Go HUD Skill →","",-1],[1,"install","Установка",0,"Положите папку аддона в проект. Больше настраивать нечего.","",-1],[1,"from-the-asset-store-or-a-release-zip","Из Asset Store или ZIP-архива релиза",1,"Распакуйте в корень проекта так, чтобы получилось res://addons/gohud/. Это всё. По желанию включите Project → Project Settings → Plugins → gohud.","",19],[1,"as-a-git-submodule","Как git-подмодуль",1,"Корень репозитория и есть папка аддона, поэтому он ложится ровно туда, где его ждёт Godot. Правьте на месте, коммитьте и пушьте внутри addons/gohud, а затем коммитьте указатель подмодуля в своей игре. Нужен Godot 4.6 или новее. gohud использует API, появившиеся в 4.5 (DPITexture, FoldableContainer, свойства доступности), поэтому на всём, что старше, он падает ещё при разборе. 4.6 — поддерживаемый минимум, записанный в GoUi.MIN_ENGINE.","git submodule add https://github.com/thruthesky/gohud.git addons/gohud git submodule update --init git -C addons/gohud checkout v1.0.0 # по желанию: закрепить тег или коммит",19],[1,"start","Быстрый старт",0,"Любой виджет — это .new() и add_child(): ни файлов сцен, ни автозагрузки.","",-1],[1,"pick-a-look-before-building-ui-optional","Выберите образ до сборки интерфейса (по желанию)",1,"","GoUi.use_preset(GoThemePresets.SCIFI_DARK) # если пропустить, используется default_dark",22],[1,"a-confirmation-you-await","Подтверждение, которое можно await",1,"Передайте destructive = true (последний аргумент) — и кнопка подтверждения нарисуется как залитая кнопка опасного действия.","var dialogs := GoDialogs.new() add_child(dialogs) if await dialogs.confirm(\"Удалить сохранение\", \"Это действие необратимо.\"): delete_save()",22],[1,"a-bottom-sheet-with-a-sticky-search-field-and-fo","Нижний лист с закреплённым полем поиска и подвалом",1,"Почему закреплённые ряды отделены от прокручиваемого тела. Положите подтверждение и отмену в body — и длинный список вытолкнет их за экран. footer() виден всегда.","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Инвентарь\") sheet.toolbar().add_child(GoStyle.line_edit(\"Поиск…\")) sheet.toolbar().visible = true for item in items: sheet.body.add_child(GoStyle.list_button(GoIconSet.BOX, item.name, _use.bind(item), Color.TRANSPARENT, item.description, false)) sheet.footer().add_child(GoStyle.button(\"Закрыть\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",22],[1,"a-hud-corner","Угол HUD",1,"","var corner := GoHudAnchor.new() corner.spot = GoHudAnchor.Spot.TOP_LEFT corner.landscape_spot = GoHudAnchor.Spot.TOP_RIGHT add_child(corner) var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) corner.add_child(hp) hp.set_values(320, 500)",22],[1,"content-that-keeps-clear-of-the-hud","Содержимое, которое держится в стороне от HUD",1,"Каждый прямоугольник обходится в том направлении, где потеря площади меньше: вниз на телефоне в книжной ориентации, вбок — в альбомной. Как HUD обходит сам себя →","form.avoid_hud = true # обходить каждый видимый GoHudAnchor joystick_anchor.reserve_space = false # …кроме тех, что появляются только под пальцем notice_anchor.avoid_peers = true # уведомление садится под закреплённый HUD, а не накрывает его",22],[1,"examples","Примеры, которые можно запустить",0,"Три способа посмотреть gohud, не написав ни строки, — и ни одному не нужны ни сервер, ни автозагрузка. Пример Как открыть Что показывает Галерея examples/gallery/gallery.tscn · F6 Все виджеты, переключатель всех установленных пресетов и полный набор иконок Средневековье examples/medieval/medieval.tscn · F6 Лист персонажа, сумка и журнал заданий; кнопки переключают железо и пергамент и открывают описание предмета Демо-приложение cd examples/demo && godot Домашний экран, открывающий галерею, обучающий тур из 15 глав, витрину и средневековый образ, с живыми виджетами и отдельной карточкой на каждый класс Демо-приложению не нужна никакая подготовка: если ссылки на аддон или кэша импорта нет, оно сообщает об этом, чинит папку и открывается заново. Его домашний экран открывает каждый пример в том же окне — нажмите 1–4 или щёлкните по строке, а полоса сверху вернёт вас назад. В туре C включает режим «кино», F11 — полный экран, Space ставит на паузу (или проигрывает текущий виджет в режиме просмотра), стрелки меняют главы, а Escape возвращает на стартовый экран. Пользуетесь ИИ-агентом для кода? Откройте все три одной командой →","cd examples/demo && godot # домашний экран; при первом запуске создаёт ссылку и импортирует bash examples/demo/run.sh # то же приложение, из корня аддона bash examples/demo/run.sh -- --open=gallery # пропустить домашний экран bash examples/demo/run.sh -- --explore=surfaces # открыть сразу на одной главе тура bash examples/demo/run.sh --record /tmp/gohud-demo.avi # запись тура в 1080p / 60 кадров в секунду",-1],[2,"copy","Вставьте это в свой ИИ-агент",0,"Откройте проект Godot в агенте, вставьте блок и отправьте. Он установит навык и дополнение, а потом расскажет, что умеет gohud. Откройте терминал в папке проекта Godot и запустите там свой ИИ-агент — например, claude. Нажмите Копировать на блоке ниже, вставьте его в агент и отправьте. Когда он закончит, перезапустите агент, если он попросит, и спросите: Что умеет gohud? Блок намеренно написан по-английски — так его точнее всего читает любой агент. Свои вопросы задавайте на любом языке: навык отвечает на том языке, на котором вы пишете.","Install gohud for this Godot 4.6+ project, then use it for all game UI (menus, HUD bars, quick slots, dialogs, bottom sheets, forms, themes). 1. Install the gohud AI skill. Claude Code - run these two commands in a shell: claude plugin marketplace add thruthesky/gohud claude plugin install gohud@gohud Any other agent (Codex, Cursor, Gemini CLI, ...): git clone --depth 1 https://github.com/thruthesky/gohud.git /tmp/gohud Copy /tmp/gohud/skills/gohud into whichever of these folders this agent reads: ~/.claude/skills/gohud, .claude/skills/gohud, .agents/skills/gohud. 2. Install the add-on itself, unless addons/gohud/plugin.cfg already exists here. In a git repository: git submodule add https://github.com/thruthesky/gohud.git addons/gohud Otherwise copy the clone to addons/gohud without its .git folder. Then run: godot --headless --path . --import (If godot is not on PATH, ask me where Godot 4.6+ is.) 3. Check the result: addons/gohud/plugin.cfg exists and the import printed no \"SCRIPT ERROR\" or \"Parse Error\" lines. 4. A new skill loads when the agent starts. Tell me if I have to restart you, then tell me what gohud can do and how to preview it. Docs: https://thruthesky.github.io/gohud/",-1],[2,"claude-code","Или две команды — Claude Code",0,"Так навык ставится как плагин Claude Code. В терминале: Уже внутри Claude Code? Тогда введите это: Затем перезапустите Claude Code и введите /gohud:features — если появился список возможностей gohud, навык установлен. Само дополнение по-прежнему должно лежать в addons/gohud: Установка →","claude plugin marketplace add thruthesky/gohud claude plugin install gohud@gohud /plugin marketplace add thruthesky/gohud /plugin install gohud@gohud",-1],[2,"agents","Где каждый агент хранит навыки",0,"Хотите поставить вручную? Положите папку skills/gohud туда, откуда читает ваш агент. Побеждает первая существующая. Агент Куда класть папку Вид команд Claude Code — плагин claude plugin install gohud@gohud /gohud:preview · /gohud:features Claude Code — только навык ~/.claude/skills/gohud /gohud preview · /gohud features Claude Code — только этот проект .claude/skills/gohud /gohud preview Codex · Cursor · Gemini CLI — другие .agents/skills/gohud —","",-1],[2,"commands","Команды, которые вы получите",0,"","",-1],[2,"gohud-preview-the-widget-gallery","/gohud:preview — галерея виджетов",1,"Открывает галерею: все виджеты, переключатель всех шести пресетов и полный набор иконок. Наберите команду внутри своего проекта Godot — и она возьмёт ваш addons/gohud; если его нет, используется копия из плагина или свежий клон. Запуск идёт в одноразовом песочном проекте, поэтому ваши автозагрузки и кэш импорта остаются нетронутыми, а окно держится открытым, пока вы его не закроете.","",32],[2,"gohud-preview-demo-the-19-chapter-guided-tour","/gohud:preview demo — обучающий тур из 15 глав",1,"Открывает демо на стартовом экране. Start demo проигрывает тур с настоящим вводом; Explore widgets даёт попробовать виджет руками. Клавиши, перечисленные в разделе Примеры, работают и здесь.","",32],[2,"many-other-commands","Множество других команд",1,"Команда Что делает /gohud:preview medieval Лист персонажа, сумка и журнал заданий в средневековых пресетах /gohud:preview demo --explore hud Демо, открытое сразу на одной главе — hud buttons inputs selection lists data states surfaces prompt touch coach scrolling forms anchors theming /gohud:preview gallery --preset scifi_dark Галерея в одном пресете; добавьте --phone для окна телефона 390×844 или --size 1920x1080 для любого размера /gohud:preview res://ui/main_menu.tscn Сцена вашего проекта, запущенная внутри этого проекта /gohud:preview list Все цели, идентификаторы пресетов и ключи глав демо /gohud:preview gallery --check Быстрая проверка без окна в headless-режиме — падает при ошибках в скриптах /gohud:features Все возможности по группам, по одной строке кода на каждую /gohud:features hud Одна область подробно — surfaces hud style theming icons i18n accessibility config Для команд предпросмотра нужен Godot 4.6 или новее в PATH.","",32],[2,"ask","Или просто попросите",0,"Или просто попросите. Навык обучает агента всему API gohud, поэтому работают и обычные просьбы — «Собери меню паузы на gohud». Если он установлен как обычный навык в ~/.claude/skills/gohud, команды пишутся через пробел: /gohud preview demo, /gohud features. Для предпросмотра нужен Godot 4.6 или новее в PATH, либо передайте --godot /path/to/godot.","",-1],[4,"gosurface-the-shell","GoSurface — оболочка",1,"Всплывающие окна, листы и выпадающие списки используют её же. Она берёт на себя безопасную область, виртуальную клавиатуру, закреплённые шапку и подвал, прокручиваемое тело, определение самого верхнего окна, восстановление фокуса, владение кнопкой «Назад» и изменение размера перетаскиванием. Размещение Как выглядит Для чего CENTER Карточка посередине Подтверждения, настройки BOTTOM Лист, поднимающийся снизу Списки, страницы управления ANCHOR Карточка, закреплённая рядом с элементом управления Выпадающие списки, контекстные меню Она не удаляет себя сама. Реагировать на close_requested — скрывать или освобождать — обязанность владеющего экрана, потому что оболочка не может знать, почему её закрывают (сохранить и закрыть или отбросить).","",-1],[4,"gosheet-a-page-from-the-bottom","GoSheet — страница снизу",1,"Он владеет собственным CanvasLayer, поэтому надёжно лежит поверх HUD. open() очищает тело и выключает кнопку «Назад» и закреплённые ряды — мёртвая кнопка на экране, откуда некуда возвращаться, читается как поломка.","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Инвентарь\") sheet.toolbar().add_child(GoStyle.line_edit(\"Поиск…\")) sheet.toolbar().visible = true sheet.footer().add_child(GoStyle.button(\"Закрыть\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",-1],[4,"godialogs-confirmations-you-await","GoDialogs — подтверждения, которые можно await",1,"confirm(title, body, ok_text, cancel_text, extra, args, destructive) — всё после текста необязательно, а alert() работает так же, но с одной кнопкой. Ставьте destructive для того, что нельзя отменить: кнопка подтверждения становится залитой кнопкой GoStyle.Tone.DANGER_SOLID. В светлой теме подкрашенная подпись опасного действия вынуждена темнеть, пока не станет читаться как чёрный текст; залитая кнопка оставляет белый текст на красном. Тон применяется заново при каждом вызове, потому что окно переиспользуется, а второй confirm() при открытом первом сразу возвращает false. confirm_key() принимает ключи перевода. Раскладка кнопок. action_layout по умолчанию равен VERTICAL (безопасно для длинных переводов), HORIZONTAL даёт один ряд с половиной ширины на каждую, а AUTO ставит их в один ряд только тогда, когда обе подписи умещаются в половину карточки одной строкой, и складывает их столбиком в остальных случаях. action_gap — это расстояние между кнопками, а body_gap — расстояние над ними; сделайте его больше, чем зазор между кнопками, чтобы вопрос и выбор читались как две части. Для одного-единственного диалога вызовите set_next_action_layout() перед его открытием. Ряд собирается при первом открытии диалога, поэтому GoDialogs в автозагрузке ничего не добавляет к старту.","if await dialogs.confirm(\"Удалить сохранение\", \"Это действие необратимо.\"): delete_save()",-1],[4,"goform-a-width-capped-form","GoForm — форма с ограниченной шириной",1,"Она гарантирует перенос строк у вложенных подписей. Без этого одно длинное предложение вытягивается в одну строку, минимальная ширина которой превосходит экран, и края обрезаются — становится не понять даже, на каком вы экране. Включать перенос вручную в каждой сцене забываешь каждый раз.","",-1],[4,"goscroll-touch-scrolling","GoScroll — сенсорная прокрутка",1,"Кладите внутрь одну вещь. Шапки и ряды кнопок место снаружи — длинный список не должен выталкивать их за экран. use_panel_edge() переносит полосу прокрутки во внутренние отступы карточки, а содержимое сохраняет свой отступ.","",-1],[5,"gonotice-snackbar","GoNotice — снекбар",1,"Он никогда не перехватывает ввод. Уведомление читают, а не нажимают. Оно не берёт фокус, не блокирует игровой ввод, и кнопка под ним по-прежнему нажимается. Когда нужно подтверждение, берите GoDialogs; когда нужен выбор — GoPromptCard.","",-1],[5,"gopromptcard-a-question-that-does-not-block","GoPromptCard — вопрос, который не блокирует",1,"Плавает сбоку без затемняющей подложки. Игра продолжает идти.","",-1],[5,"gocoachmark-guided-tour","GoCoachMark — обучающий тур",1,"Указывает на настоящие элементы управления, по одному за раз. Ввод берёт только карточка, поэтому нажатие на сам подсвеченный элемент двигает тур дальше — «нажмите здесь» становится действием, а не предложением. title и body могут быть ключами перевода или обычным текстом. Шаг, чья цель исчезла, пропускается.","tour.start([ {\"target\": bag_button, \"title\": \"Сумка\", \"body\": \"Всё, что вы подбираете, попадает сюда.\"}, {\"target\": map_button, \"title\": \"Карта\", \"body\": \"Нажмите, чтобы открыть карту целиком.\"}, ])",-1],[6,"the-small-things-decide-whether-it-looks-good","Вид решают мелочи",1,"Вылизывайте крупные панели сколько угодно — глаз всё равно цепляется за мелочь: слово, разорванное надвое, обрезанное свечение, тесный слот. Четыре такие мелочи были указаны 2026-09-13 и исправлены в виджетах и темах, а не в демонстрационном экране, так что тот же результат получает каждый экран. Что было видно Причина Исправление У обучающей подсказки Done превращалось в Don/e Кнопка с включённым переносом вычитает ширину своего текста из минимума — сожмите её, и она разорвётся внутри слова GoStyle.fit_words(): одно слово не переносится никогда; несколько слов переносятся, но самое длинное слово всегда помещается — и судят по отображаемому тексту, а не по ключу перевода, а форма применяет это заново при смене языка У кнопки во всю ширину свечение обрезалось по вертикали слева Контейнер прокрутки обрезает всё по своему краю, без исключений. Уцелел только правый край — благодаря жёлобу под полосу GoScroll занимает у родителя отступ, чтобы отодвинуть свой край на 12dp наружу, и возвращает его внутри — содержимое остаётся на месте Время, иконка и количество встали в слоте столбиком Три ряда внутри 48dp Крупная иконка по центру, горячая клавиша слева вверху, количество — значком справа внизу, оставшееся время — значком поверх иконки; панели значков берутся из badge_box() скина Плоский выпадающий список без видимого выбора Наведение на пункт использовало панель кнопки, а радиометки были бледными стандартными метками движка Отдельная панель наведения (мягкая акцентная подкраска), та же графика радиокнопок, что и у флажков, высота пункта под палец Выпадающий список — панель наведения и радиометка Слоты — угловые значки и оставшееся время (sci-fi) Давайте кнопкам без подписи описание через GoStyle.icon_button(icon, action, -1, tooltip_key) — и всплывающая подсказка для мыши, и имя для программ чтения с экрана берутся из этого одного значения. Подсказку gohud рисует сам: стандартная подсказка движка разбивает текст по одному символу на строку, когда её расчёт ширины идёт не так (измерено на ширине 1dp). Карточка обучающей подсказки держится в стороне от неподвижных элементов В альбомной ориентации карточку раньше отправляло к самому верхнему или нижнему краю — ровно туда, где живут шапки и элементы HUD; в демо она садилась на → × в шапке. Теперь она держится на одном уровне с целью, обходит любой GoHudAnchor, который резервирует место, и принимает прочие препятствия через keep_clear. Она смещается на кратчайшее расстояние, которое обходит препятствие, не закрывая цель, и остаётся на месте, когда экран слишком мал, чтобы обойти всё, — перекрытие лучше исчезновения. Её глубина — то, за счёт чего она читается над страницей, — задаётся регуляторами скина (float_shadow_size, float_shadow_lift, float_shadow_alpha; скины со срезанными углами используют float_glow_size).","tour.keep_clear = [header_bar, toolbar] # неподвижные элементы, которые не являются якорями",-1],[6,"screens-with-a-mouse-and-a-keyboard","Экраны с мышью и клавиатурой",1,"У пальца нет состояния наведения. Разрабатывайте только под мобильные — и два состояния, существующие лишь на настольном компьютере, останутся непроверенными; одно из них и было сломано: у gohud кольцо фокуса было невидимо на основной кнопке. Панель была акцентного цвета, и кольцо тоже: 1.00:1, один и тот же цвет, нарисованный поверх себя. При перемещении с клавиатуры понять, где вы находитесь, было нельзя. Сверху вниз: обычное · наведение · фокус. Залитые кнопки получают кольцо, контрастное их панели. Залитые кнопки (GoPrimaryButton, GoDangerSolidButton) используют кольцо, контрастное их собственной панели: тёмное в тёмной теме, белое в светлой, тёмная прицельная скобка в sci-fi. Проверка контраста измеряет кольцо фокуса относительно панели, на которой оно лежит, поэтому правило переживает смену палитры (WCAG 2.4.11 требует 3:1 для индикаторов фокуса).","",-1],[6,"hud-widgets","Виджеты HUD",0,"","",-1],[6,"gohudanchor-nine-spots","GoHudAnchor — девять точек",1,"Учитывает безопасную область и краевые отступы. Задайте ему landscape_spot — и он переедет в альбомной ориентации: элементы управления, стоящие снизу по центру в книжной, могут уйти вправо вниз. Зачем он нужен. Написанные вручную для каждого элемента HUD, якоря и смещения расходятся: полоса здоровья оказывается под вырезом камеры на устройстве с чёлкой, а кнопка управления садится на жест-бар в альбомной ориентации. Эта арифметика живёт в одном месте. Как держать содержимое из-под HUD Когда прокручиваемый экран делит дисплей с HUD, содержимое уезжает под него, и два набора текста накладываются, пока не перестают читаться оба. В этом аддоне такое случалось дважды: подсказка поля ввода выдавливалась между быстрыми слотами, а рукоятка переключателя в настройках садилась на полосу здоровья. Каждый прямоугольник обходится в том направлении, где теряется меньше площади. Полоса в правом верхнем углу обходится вниз на телефоне в книжной ориентации (13% высоты) и вбок — в альбомной (21% ширины): обход по вертикали в альбомной стоил бы 27% экрана. Уже отданная площадь вычитается до того, как будет измерен следующий прямоугольник. Элементы HUD сталкиваются и друг с другом Девять точек делят экран; они не гарантируют, что элементы разойдутся между собой. Широкий снекбар сверху по центру садился прямо на полосу здоровья справа вверху и прятал значение — сколько осталось здоровья, прочесть было нельзя. Он отходит только по вертикали — смещение ещё и вбок заставляло бы центрированное уведомление появляться каждый раз в новом месте. И обходит он только те элементы, которые не отходят сами: если уступают оба, эти двое будут меняться местами вечно.","form.avoid_hud = true # обходить каждый видимый GoHudAnchor joystick_anchor.reserve_space = false # …кроме тех, что появляются только под пальцем notice_anchor.avoid_peers = true # садится под закреплённый HUD notice_anchor.reserve_space = false # и не двигает страницу, пока висит",47],[6,"gobar-health-mana-experience","GoBar — здоровье, мана, опыт",1,"Изменения плавно идут 0.18с — полоса здоровья, которая прыгает, не рассказывает, насколько сильно вас ударили. reduce_motion делает их мгновенными. Большие числа сокращаются до 12.3k, чтобы ширина полосы не дёргалась от появления и исчезновения цифр.","var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) # токен только для заливки hp.set_values(320, 500) # \"320 / 500\"",47],[6,"goslot-one-quick-slot","GoSlot — один быстрый слот",1,"Иконка, количество, перезарядка и горячая клавиша на одной лицевой панели. Если навешивать значки на маленький круг, каждый слот получает свою ширину и ряд начинает гулять. Видимый размер и размер нажатия — разные вещи. У плотно стоящих слотов области нажатия в 48dp перекрываются; перекрытие достаётся тому слоту, чей центр ближе — расскажите им друг о друге через touch_peers. keyboard_focus по умолчанию выключен, чтобы ряд из восьми слотов не вставал между пользователем клавиатуры и всеми элементами настроек в порядке обхода Tab. Включайте его, когда клавиатура или геймпад — единственный ввод.","",47],[6,"gojoystick-virtual-stick","GoJoystick — виртуальный стик",1,"Режим Поведение FIXED Всегда на одном месте — легко найти, не глядя FOLLOW Появляется там, куда лёг большой палец RELATIVE Продолжает следовать за пальцем после появления — удобно для долгого движения Длина Vector2 из сигнала moved лежит в пределах 0–1, поэтому его можно сразу умножать на скорость; от размера экрана и DPI он не зависит.","",47],[6,"goiconbutton-looks-small-presses-large","GoIconButton — выглядит маленькой, нажимается большой",1,"Безопасна, только пока соседи игнорируют ввод. Если расширенная область накроет следующую кнопку, та перестанет отзываться. Стоящим рядом кнопкам-иконкам нужен touch_peers.","",47],[7,"gosnackbar-the-message-that-places-itself","GoSnackbar — сообщение, которое само встаёт на место",1,"Садится снизу (или сверху), над безопасной областью и клавиатурой, и уходит сам. Без него слой, размещение, таймер и уборку вы пишете на каждом экране, которому нужно сказать «сохранено». Сообщения встают в очередь, а не затирают друг друга, и повторы одной и той же строки объединяются — сервер, падающий четыре раза в секунду, больше не копит четыре минуты уведомлений. Снекбар без кнопки пропускает ввод сквозь себя, поэтому игра под ним продолжает идти. Здесь ни о чём не спрашивают. Он уходит сам, и игрок может его вовсе не увидеть. Необратимые подтверждения — дело GoDialogs. Кнопки здесь должны быть необязательными: «Отменить», «Подробнее», «Повторить». GoNotice — вторая половина пары: он никогда не берёт ввод и фокус, а место ему назначает экран, которому он принадлежит. Кнопку он держать не может; этот — может.","snack.show_text(\"Сохранено\", GoTheme.SUCCESS) # Возможность отменить — 0 это первая кнопка, -1 означает, что время вышло if await snack.post({\"text\": \"Предмет выброшен\", \"actions\": [\"Отменить\"]}) == 0: restore_item()",-1],[7,"gospinner-a-wait-with-no-end-in-sight","GoSpinner — ожидание без видимого конца",1,"Играм, которые разговаривают с сервером, это нужно больше всего остального на этой странице: замерший экран читается как вылет. Один вызов превращает нажатую кнопку в спиннер на её же месте. Кнопка сохраняет свой размер — подпись становится прозрачной, а не исчезает, поэтому ряд не прыгает, — и на время вращения она отключена. Вторая часть и есть суть: покупка не должна сработать дважды, пока вы await. При включённом reduce_motion он не вращается; вместо этого пульсируют три точки. Прогресс, который можно измерить, — это GoBar. Спиннер ничего не обещает о том, когда закончится.","GoSpinner.busy(buy_button, true) var ok := await server.purchase(item) GoSpinner.busy(buy_button, false)",-1],[7,"gobadge-the-unread-dot-the-new-tag-the-99","GoBadge — точка непрочитанного, метка НОВОЕ, 99+",1,"Он висит на правом верхнем углу носителя на якорях, поэтому следует за носителем, чей размер определится позже, а повторное навешивание возвращает тот же значок. Берите число, когда от количества зависит, что игрок сделает, и точку — когда важно только «там что-то есть». Цвет его текста подбирается по контрасту с тем цветом, которым значок покрасил скин, — белый никогда не предполагается заранее, — и у него есть доступное имя, потому что цветная точка ничего не говорит программе чтения с экрана.","GoBadge.attach(mail_button, unread_count) # при нуле прячется сам GoBadge.attach(shop_button, 0, \"НОВОЕ\") GoBadge.attach(friend_button, 3, \"\", true) # точка — «там что-то есть»",-1],[8,"gofield-the-row-that-can-be-wrong","GoField — строка, которая может быть неверной",1,"Одна строка наверху формы из пяти полей со словами «проверьте ввод» не говорит, какое поле. Именно из-за этого одного бросают регистрацию. Пока показана ошибка, подсказка прячется, поэтому строка не вырастает на строку и не выталкивает всё, что под ней, а текст ошибки подмешивается в доступное имя элемента управления — одна красная рамка ничего не говорит тому, кто не видит красного. GoStyle.field() — статичный вариант: подпись, элемент управления, подсказка, без состояния ошибки. Берите фабрику там, где ничего не может пойти не так, и узел — везде, где сервер может отказать.","var name_field := GoField.make(\"Имя персонажа\", GoStyle.line_edit(\"2-12\"), \"Изменить потом нельзя\") name_field.set_error(\"Это имя занято\") # сервер сказал «нет» name_field.clear_error()",-1],[8,"goinputgroup-an-input-welded-to-its-button","GoInputGroup — поле ввода, сваренное со своей кнопкой",1,"Решает он углы. Две скруглённые формы, встречающиеся посередине, выглядят защемлёнными, а стандартный зазор заставляет читать их как два предмета. Внешние углы остаются круглыми, соприкасающиеся становятся прямыми — во всех состояниях кнопки, иначе группа распадается в момент нажатия. У скинов со срезанными углами полей для углов нет вовсе, поэтому там он их не трогает, и прямые грани сходятся чисто.","GoInputGroup.make(GoStyle.line_edit(\"Сообщение\"), {\"suffix\": GoStyle.icon_button(&\"send\", send)}) GoInputGroup.make(GoStyle.line_edit(\"Имя\"), {\"prefix_icon\": &\"search\"})",-1],[8,"gocombobox-a-picker-that-searches","GoCombobox — выбор с поиском",1,"Меньше десяти пунктов — лучше GoStyle.select(): на одно нажатие меньше, и виден весь список. После тридцати просматривать глазами становится работой. Поиск совпадает внутри названий, а не только с их началом. Поиск по префиксу почти ничего не находит в корейских и японских списках, где слово, отличающее два пункта друг от друга, редко оказывается первым.","var picker := GoCombobox.make(server_names, 0, \"Выберите сервер\") picker.picked.connect(func(i: int) -> void: connect_to(servers[i]))",-1],[8,"gocodeinput-coupon-and-gift-codes","GoCodeInput — купоны и подарочные коды",1,"Код куда чаще вставляют из сообщения, чем набирают. Двенадцать настоящих полей ломали бы вставку на первой ячейке и теряли символы в IME, поэтому текст принимает одно скрытое поле, а ячейки рисуются. ABCD-EFGH-IJKL теряет дефисы по дороге.","var coupon := GoCodeInput.make(12, 4) coupon.completed.connect(func(code: String) -> void: server.redeem(code)) coupon.set_error(\"Уже использован\")",-1],[8,"gotable-sortable-headers-selectable-rows","GoTable — сортируемые заголовки, выбираемые строки",1,"numeric: true, иначе рейтинг перевернётся. При сравнении как текста \"9124\" оказывается больше \"91240\" — а у очков, золота и урона количество цифр всегда разное. row_selected отдаёт индекс в вашем исходном массиве, а не позицию после сортировки. Направление сортировки показано знаком, а не только цветом, и нажимается строка целиком, чтобы никому не приходилось попадать в одну ячейку. GoStyle.table() остаётся сеткой только для чтения.","var board := GoTable.make( [{\"text\": \"Место\", \"width\": 56}, {\"text\": \"Имя\"}, {\"text\": \"Очки\", \"numeric\": true}], rows) board.row_selected.connect(func(i: int) -> void: open_profile(rows[i]))",-1],[8,"gopagination-pages-or-a-more-row","GoPagination — страницы или строка «Ещё»",1,"Номера — интерфейс под мышь; на телефоне строка «Ещё» читается лучше. Текущая страница держится в середине окна, поэтому нажатие «дальше» не перетасовывает все номера. Всего 0 означает «неизвестно», и рисуются только стрелки — число страниц, которого ему не дали, он не выдумывает.","var pager := GoPagination.make(1, 12, func(page: int) -> void: load_mail(page)) var more := GoPagination.more(load_next) # вариант для мобильных",-1],[9,"gorewardcalendar-daily-attendance","GoRewardCalendar — ежедневный вход",1,"Выбор даты в игре почти никогда не нужен. А форма календаря — нужна: для наград за вход, где важно, какой у вас день подряд, а не какое сегодня число. Нажимается только сегодняшняя ячейка — кнопка, которая на нажатие не отвечает, читается как сломанная. Полученное, сегодняшнее и будущее различаются сразу тремя вещами: знаком галочки, акцентной рамкой и притемнением.","var attendance := GoRewardCalendar.make(days, claimed_until) attendance.claimed.connect(func(day: int) -> void: server.claim_day(day))",-1],[9,"goradar-and-godonut-stats-at-a-glance","GoRadar и GoDonut — характеристики с одного взгляда",1,"Значения радара лежат в 0–1, потому что «сколько это — полностью» решает игра: сырые 120 STR рядом с 45 INT нарисовали бы неправду. Значения кольца сырые, и делит за вас оно само; после пяти долей остальное сворачивается, потому что шестая доля — ниточка, которую никто не прочтёт. Линия сравнения пунктирная, а не просто другого цвета, а легенда пишет процент словами.","var stats := GoRadar.make({\"STR\": 0.85, \"AGI\": 0.5, \"INT\": 0.3, \"VIT\": 0.7, \"LUK\": 0.45}) stats.set_compare(with_new_sword) # пунктирный слой поверх var share := GoDonut.make([{\"label\": \"Физический\", \"value\": 620}, {\"label\": \"Магический\", \"value\": 340}]) card.add_child(share.legend())",-1],[9,"gocarousel-banners-and-character-select","GoCarousel — баннеры и выбор персонажа",1,"Сам он не листается, пока вы не попросите, и пять секунд — нижняя граница: баннер, который меняется каждые три, забирает текст раньше, чем его прочтут. Касание сбрасывает таймер, а при включённом reduce_motion он не листается сам никогда. Точки нажимаются по минимуму для пальца, хотя нарисованная точка мала.","banners.set_pages([promo, event, pack]) banners.autoplay_seconds = 5.0 # по умолчанию выключено",-1],[9,"gokbd-key-hints-that-do-not-lie","GoKbd — подсказки клавиш, которые не врут",1,"Жёстко вписанное «Нажмите F» продолжает говорить F после того, как игрок переназначил клавиши, — самая частая ложь в интерфейсе для ПК. for_action() читает InputMap; если действие привязано к геймпаду, он возвращает пустоту и виджет прячется, потому что «Нет» было бы ложью само по себе. На Android и iOS он прячется сам.","hint.add_child(GoKbd.for_action(&\"interact\")) # читает настоящую привязку",-1],[10,"godrawer-the-side-panel","GoDrawer — боковая панель",1,"GoSheet приходит снизу, и для телефона в книжной ориентации это правильно. На планшете или настольном компьютере тот же лист накрывает игру — там панель приходит сбоку. Панель доходит до края экрана, а содержимое остаётся внутри безопасной области, иначе скруглённый угол срежет первую строку. LEFT означает левый край экрана даже в арабском; включите follow_text_direction, когда смысл именно в «стороне начала», и она перевернётся при письме справа налево.","bag.side = GoDrawer.Side.RIGHT bag.open(\"Сумка\")",-1],[10,"gopopover-the-anchored-card","GoPopover — карточка с привязкой",1,"Это привязанное размещение GoSurface, где слой, поверхность, якорь и уборка уже связаны, — те десять строк, которые каждая игра пишет снова и снова. Открыта всегда одна, потому что сложенные стопкой карточки хоронят экран и понять, какая карточка какому слоту принадлежит, нельзя. Подложка прозрачная: карточка, открытая, чтобы сравнить снаряжение, не должна это снаряжение затемнять. Это не всплывающая подсказка по наведению. У касания наведения нет, поэтому всё, что может открыть только мышь, для половины ваших игроков невидимо.","GoPopover.open(slot, item_card(item))",-1],[10,"gocontextmenu-long-press-and-right-click","GoContextMenu — долгое нажатие и правый клик",1,"PopupMenu в движке уже есть. Чего нет — так это жеста: полсекунды до открытия, отмена в тот момент, когда палец сдвинулся, поэтому прокрутка списка меню не вызывает никогда. Передайте Callable вместо массива, когда пункты зависят от того, на что нажали. Долгому нажатию нужен второй вход. Скрытый жест не находит никто — дайте ему в пару видимую кнопку ⋯ (open_at()), иконку или обучающую подсказку при первом запуске.","GoContextMenu.attach(item_slot, [ {\"text\": \"Использовать\", \"action\": use}, {\"separator\": true}, {\"text\": \"Выбросить\", \"action\": drop, \"danger\": true}, ])",-1],[10,"goconsole-the-developer-console","GoConsole — консоль разработчика",1,"Читерские и отладочные команды, с палитрой, которая фильтрует по мере набора, чтобы их не приходилось запоминать, и с историей на клавишах со стрелками. Она лежит поверх всего, поэтому отлаживать можно и поверх диалога. В релизной сборке она открываться отказывается. debug_only включён по умолчанию; читерские команды в руках игрока кончают экономику игры в первый же день.","console.register(\"give\", \"Выдать предмет: give <id> <count>\", give) console.toggle()",-1],[11,"list-rows-with-a-description","Строки списка с описанием",1,"Строка со второй строкой текста получает равные верхний и нижний отступы, просторнее однострочной, а пара «заголовок и описание» остаётся выровненной по вертикали рядом с иконкой — в том числе когда контейнер растягивает строку выше и когда описание переносится на несколько строк. Вся строка при этом остаётся одной целью нажатия. Двухстрочные строки, слоты и полосы в средневековом примере — те же вызовы фабрики под medieval_light.","GoStyle.list_button(GoIconSet.SWORD, \"Хранитель клятвы\", _inspect, Color.TRANSPARENT, \"Длинный меч / Атака 42\", false)",-1],[11,"flowing-rows","Перетекающие ряды",1,"Кладите элементы управления в wrap_row при их естественной ширине. Если перенос оставить включённым, минимальная ширина кнопки падает почти до нуля, и ряд меряет свою ячейку по ней — подпись схлопывается до одного символа на строку. Фабрика не даёт этому случиться.","",-1],[11,"never-leave-an-empty-list-empty","Никогда не оставляйте пустой список пустым",1,"Пустой экран люди читают как сломанный.","page.add_child(GoStyle.empty_state(GoIconSet.BOX, \"Здесь пока пусто\"))",-1],[11,"hooks","Хуки для наследования",0,"Каждое место, где создаётся дочерний виджет, проходит через переопределяемый метод, поэтому проект, наследующий типы gohud, может получить свои подклассы внутри виджетов, не копируя код. Хук Виджет По умолчанию _make_scroll() GoCoachMark, GoSurface GoScroll.new() _make_close_button() GoPromptCard, GoSurface GoIconButton.new() _make_surface() GoSheet, GoDialogs GoSurface.new() _should_pause() GoCoachMark Скрывает карточку, пока открыто модальное окно","",-1],[13,"pick","Как выбрать",0,"Эта одна строка меняет тему, скин и иконки. Из редактора это делается через Project Settings → Gohud → Theme → Preset, из ресурса настроек — через GoConfig.preset.","GoUi.use_preset(GoThemePresets.SCIFI_DARK)",-1],[13,"keeping-one-field-your-own","Оставить одно поле своим",1,"Явно заданные theme, skin или icons берут верх над пресетом.","GoUi.use_preset(GoThemePresets.SCIFI_DARK) GoUi.config.icons = my_icons # ваши иконки, всё остальное — из пресета",74],[13,"the-six-built-in-presets","Шесть встроенных пресетов",1,"Пресет Панели Скин · иконки default_dark · default_light Скруглённые панели StyleBoxFlat на градуированной шкале теней; основные кнопки поднимаются и проседают при нажатии GoSkin · 84 иконки по умолчанию scifi_dark · scifi_light Панели GoStyleBoxCut со срезанными углами, неоновой гранью и свечением; фокусные метки GoStyleBoxBracket GoSkinSciFi — шестиугольный стик · иконки по умолчанию medieval_dark · medieval_light Кованые рамки GoStyleBoxMedieval — железо и кожа либо пергамент — с заклёпками и угловыми орнаментами на меню GoSkinMedieval · 16 гравированных иконок поверх стандартных","",74],[13,"medieval","Средневековье: железо, кожа и пергамент",0,"medieval_dark соединяет тёмное железо и кожу со старым золотом. medieval_light берёт пергамент и чернила. Оба используют GoSkinMedieval, те же виджеты и 16 оригинальных иконок с гравировкой; иконки навигации откатываются к исходному набору. Выбирайте пресет до создания интерфейса. Явные переопределения GoConfig.theme, skin или icons по-прежнему имеют приоритет. Откройте res://addons/gohud/examples/medieval/medieval.tscn и нажмите F6 — увидите рабочий лист персонажа, сумку и журнал заданий. Его кнопки переключают варианты и открывают описание предмета. Железо и кожа Пергамент и чернила У рамок меню есть заклёпка и небольшой угловой орнамент; всегда видимый HUD сохраняет сдержанную грань. Здоровье, мана и выносливость заливаются красным, синим и оливковым. Cinzel ограничен заголовками и подзаголовками; основной текст сохраняет шрифт проекта или шрифт по умолчанию. Лицензия встроенного шрифта лежит в assets/fonts/cinzel/OFL.txt. Гравированный набор перерисовывает bag, book, box, coin, crown, flag, heart, key, map, potion, shield, star, sword и user, а также добавляет scroll и seal. Любое другое имя откатывается к набору по умолчанию, поэтому close и settings сохраняют свои стандартные рисунки в любом пресете. Cinzel покрывает латиницу; для локализованных заголовков задайте собственный шрифт через shape.fonts. Что набор тестов проверяет для обоих вариантов. Что выбран средневековый скин; что панели меню и HUD — кованые рамки, причём орнамент только на меню; что заголовки идут шрифтом Cinzel, а основной текст сохраняет унаследованный шрифт; что гравированные иконки импортируются как DPITexture; что настоящий быстрый слот использует скин; что изменение регуляторов у копии скина доходит до слота, не трогая пресет; и что обратное переключение восстанавливает геометрию стандартного и sci-fi вариантов.","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # Или: GoUi.use_preset(GoThemePresets.MEDIEVAL_LIGHT)",-1],[13,"make-a-kingdom-of-your-own","Сделайте собственное королевство",1,"JSON-темы могут наследовать другие JSON-темы. Пропущенные значения сохраняют настройки родителя; циклическое наследование отвергается. Сгенерированный пресет сохраняет набор иконок родителя. Настройка Действие shape.material 0: железо · 1: кожа · 2: пергамент. Управляет фактурой поверхности. shape.grain_alpha Непрозрачность фактуры. Поставьте 0 для чистой поверхности. shape.ornament_scale · shape.bevel_strength Размер углового орнамента меню и сила фасочного блика. shape.fonts Сопоставляет роли title, subtitle, caption, body и button со шрифтами res:// внутри аддона. Пропущенные роли сохраняют унаследованный шрифт. skin.dials Радиус быстрого слота, видимость заклёпок, фактура и блик. Полная таблица ниже перечисляет каждый регулятор.","python3 addons/gohud/tools/new_theme.py kingdom --from medieval_dark # Отредактируйте themes/palettes/kingdom.json, затем: python3 addons/gohud/tools/make_theme.py kingdom godot --headless --path . --import # В GDScript, до создания виджетов: GoUi.use_preset(&\"kingdom\")",77],[14,"colours","Цвета",1,"Имя Для чего background Подложка экрана surface · surface_soft · surface_high Три слоя панелей — панель, карточка, приподнятая ячейка border Границы карточек и кнопок text · secondary · muted Три уровня текста — основной, вспомогательный, приглушённый accent · on_accent Акцент и текст, положенный поверх него success · warning · danger · info Текстовые цвета состояний *_fill Те же состояния в виде заливки — для полос и других крупных областей scrim · shadow · track Завеса за всплывающими окнами, тени, жёлоб полосы Зачем нужен *_fill. Смысл один, требования противоположные. warning в роли текста должен быть достаточно тёмным, чтобы читаться на светлом фоне; в роли заливки полосы опыта он должен быть достаточно ярким, чтобы его заметили. Один токен не может быть и тем, и другим — полоса в светлой теме уходила в коричневый. Тема без варианта _fill автоматически откатывается к базовому имени, поэтому темы, созданные до появления этих токенов, продолжают работать.","",-1],[14,"measurements-dp","Размеры (dp)",1,"touch button_height gap_tiny gap_small gap gap_large padding padding_compact compact_padding_x compact_padding_y radius_small radius radius_large screen_margin scroll_deadzone scroll_edge scrollbar_width list_glyph icon_size notice_duration_ms","",-1],[14,"panel-opacity","Непрозрачность панели (%)",1,"panel_alpha card_alpha hud_alpha notice_alpha popup_alpha — насколько плотное лицо у контейнера. По умолчанию 80, чтобы игра оставалась видна за диалогом; у popup_alpha — 100. Тема без этих токенов откатывается к 100 и рисуется ровно так же, как раньше. Итоговое значение читается как доля через GoUi.surface_alpha(variant); правила собраны в разделе Непрозрачность — игра за панелью.","",-1],[14,"text-roles","Текстовые роли",1,"micro · compact · caption · body · button · subtitle · title — роль называет размер, а не назначение. «Самый крупный текст», а не «заголовок». Так шкала остаётся верной, даже когда экран применяет её для чего-то другого.","",-1],[14,"type-variations","Вариации типов",1,"GoPanel GoCard GoButton GoPrimaryButton GoDangerButton GoDangerSolidButton GoBareButton GoCompactButton GoIconButton GoListButton GoTitleLabel GoSubtitleLabel GoCaptionLabel GoCompactLabel GoMicroLabel","",-1],[15,"five-layers-most-specific-first","Пять слоёв, от самого частного",1,"Порядок Где Единица Охват ① аргумент прямо в вызове — surface.alpha, GoStyle.card(…, alpha) доля 0.0–1.0 одно окно ② GoConfig.container_alpha_overrides[kind] доля 0.0–1.0 один вид панелей во всём проекте ③ GoConfig.metric_overrides[<kind>_alpha] процент проекты, которые держат все размеры в одном месте ④ GoConfig.container_alpha доля 0.0–1.0 все панели разом ⑤ GoHud/constants/<kind>_alpha в самой теме процент то, что решает облик, — источник истины Если не задан ни один из них, значение равно 100 — значит, в старой теме не меняется ничего. Непрозрачность везде — доля, кроме как в теме. Любое поле alpha и любой аргумент принимают 0.0–1.0 — те же единицы, что у Color.a и modulate.a, а отрицательное значение означает «не задано». Единственное исключение — константы темы: константа Theme не умеет хранить дробное число, поэтому и они, и перекрывающий их канал (metric_overrides, у которого те же имена и тот же целочисленный тип, что у темы), записываются как 80. Больше нигде.","# Только одно окно — диалог подтверждения, который не должен закрыть бой за собой surface.alpha = 0.6 sheet.alpha = 0.7 dialogs.alpha = 0.9 # поля @export — тоже доли drawer.alpha = 0.7 GoPopover.open(slot, body, {\"alpha\": 0.9}) var glass := GoStyle.card(Color.TRANSPARENT, -1.0, -1.0, -1.0, 0.5) # По видам — HUD держим почти плотным, ведь его текст лежит прямо поверх мира GoUi.config.container_alpha_overrides = { GoTheme.BOX_PANEL: 0.7, # диалогам и листам можно дышать GoTheme.BOX_HUD: 0.95, } GoUi.refresh() # перерисовывает уже открытые виджеты # Весь проект — пёстрому миру панели нужны обратно плотными GoUi.config.container_alpha = 1.0 GoUi.refresh() GoUi.surface_alpha(GoTheme.BOX_PANEL) # итоговая доля, например 0.8",-1],[15,"what-follows-the-value-and-what-does-not","Что следует за значением, а что нет",1,"Следуют — контейнеры Игнорируют — то, что нажимают, и метки GoSurface (единая оболочка за диалогами, листами и выпадающими списками) · GoSheet · GoDialogs · GoDrawer · GoPopover · GoNotice · GoSnackbar · GoPromptCard · GoCoachMark · GoConsole каждая кнопка · GoSlot (быстрые слоты) · GoBadge · сегментированные переключатели · ячейки выбора · чипы · круги и аватары GoStyle.card() · hud_panel() · overlay_panel() · alert() · plate() · edge_card_panel() · style_notice_panel() · floating() · box() · surface() весь текст и все иконки Кнопка с размытым состоянием перестаёт говорить, что она такое, а значок существует ради того, чтобы два символа читались. Ни то, ни другое не контейнер — значит, значению они и не следуют. Всплывающие меню остаются плотными (popup_alpha 100). Движок может поселить PopupMenu в отдельном Window, а там система не смешивает его с игрой: полупрозрачность выходит чёрной, а не просвечивающей. Снижайте её только в проектах, которые встраивают свои подокна (gui_embed_subwindows).","",-1],[15,"three-details-that-come-from-real-screens","Три подробности, добытые на живых экранах",1,"Значение умножает, а не заменяет. У лица HUD по умолчанию альфа уже 0.92, поэтому hud_alpha 80 даёт 0.736 — тема, намеренно сделавшая лицо полупрозрачным, сохраняет своё решение. Обратная сторона: примените его дважды — и панель погаснет дважды. Поэтому альфа умножается ровно в одном месте (GoSkin.surface_box()), а все остальные функции лица передают аргумент дальше, вместо того чтобы гасить собственный результат. Какой цвет передали, такой и получите. GoStyle.plate(…, fill) сохраняет явную заливку ровно такой, какой её дали: Color(ink, 0.14) уже называет свою альфу, и домножение непрозрачности панели урезало бы замысел вызывающего второй раз. GoStyle.floating(…, opaque = true) игнорирует значение по той же причине — залить лицо плотно и есть весь смысл этого флага. Панели, которые собрал не gohud, живут по тому же правилу. GoStyle.fade_panel(node) — после того как узел попал в дерево, чтобы он прочитал унаследованную тему. Вызов идемпотентен: исходное лицо запоминается, и каждый вызов пересчитывает от него, так что повторные перерисовки не накапливаются. После смены темы GoStyle.forget_face(node) сбрасывает эту память, и следующий вызов возьмёт уже новое лицо.","",-1],[15,"custom-faces-fade-too-and-that-is-the-part-that","Собственные лица гаснут тоже — и именно здесь всё ломается молча",1,"Панель со срезанными углами (GoStyleBoxCut) и кованая рамка (GoStyleBoxMedieval) — не StyleBoxFlat: они рисуют себя сами. Положите непрозрачность только в плоскую ветку — и эти темы тихо её проигнорируют, а все проверки по значениям всё равно пройдут. Обе гасят свой фон и держат свечение, заклёпки, угловую гравировку и фаски в полную силу — а фактура и фаска средневекового лица всегда были пропорциональны альфе его фона, поэтому они бледнеют вместе с панелью. Отсюда и более общий вывод: bg_color.a == 0.8 — это число. Мир просвечивает, а текст по-прежнему читается — вот требование. Первое gohud проверяет набором тестов в headless-режиме, второе — рисуя панели поверх диагональных полос на виртуальном мониторе (tests/gohud_alpha_shot.gd): на плоском лице, на срезанном и на кованом, в тёмной теме и в светлой.","",-1],[16,"shapes-styleboxflat-cannot-make","Формы, которые StyleBoxFlat не умеет",1,"Класс Что рисует GoStyleBoxCut Диагонально срезанные углы, одну утолщённую акцентную грань, внешнее свечение GoStyleBoxBracket Только угловые метки, оставляя содержимое незамкнутым GoStyleBoxMedieval Кованую рамку — заклёпки, угловую гравировку, фасочный блик и фактуру железа, кожи или пергамента Все три сериализуются в ресурс Theme, как любой другой StyleBox, — именно это и позволяет теме менять форму. Задавайте внутренние отступы через content_margin_*. При наследовании StyleBox в GDScript _get_style_margin() не вызывается никогда (проверено на Godot 4.7). Заполняйте встроенные поля, иначе содержимое прижмётся к рамке.","",-1],[17,"what-you-can-change-on-one-page","Что можно менять — на одной странице",1,"Где Что Как from родительская тема dark · light · scifi_dark · medieval_dark · … либо другая JSON-тема. Пропущенные ключи наследуют её значения; цикл наследования приводит к ошибке palette фон · три поверхности · граница · три оттенка текста · акцент · четыре цвета состояний · scrim · тень · жёлоб полосы \"#RRGGBB\", альфа — как \"#RRGGBB@0.35\" насыщенные цвета только для заливки *_vivid сохраняют полосы сочными даже тогда, когда цвету текста приходится темнеть; пропустите один — и сборщик об этом скажет читаемость руками не настраивается. Текст, границы, акцент и подпись на нём сборщик подтягивает сам, пока они не пройдут пороги, — меняйте только акцент, и проверки всё равно пройдут shape kind flat (скруглённые) · cut (срезанные углы) · medieval (кованые рамки) размеры radius · radius_small · radius_large · gap · gap_small · gap_large · padding · button_height · button_padding[4] — токены едут следом, поэтому панели и расчёты виджетов никогда не расходятся только для cut cut_ratio · cut_max · corners (diagonal|all) · glow · edge только для medieval material (0 железо · 1 кожа · 2 пергамент) · grain_alpha · ornament_scale · bevel_strength · fonts — title, subtitle, caption, body, button, сопоставленные со шрифтами res:// внутри аддона skin base — семейство для тех мест, которые код рисует сам (стик, слоты, значки, кольцо обучающей подсказки, чипы, разделители) default · scifi · medieval dials — числа этих мест: ширина и подкраска рамки слота, отступы значка, непрозрачность чипов и оповещений, ширина и непрозрачность кольца стика, размеры sci-fi фасок, свечение и скобка Каждое родительское значение расписано в JSON. Сборщик пишет их в themes/skins/gohud_skin_<id>.tres — код скина при этом не трогается. Менять сами рисунки нужно лишь через --new-skin, который создаёт заготовку подкласса GoSkin icons набор иконок путь res:// к ресурсу GoIconSet — при пропуске сохраняется от родительской JSON-темы dark · title как его показывает список выбора логическое значение · строка","",-1],[17,"every-dial","Все регуляторы",1,"Таблицу ниже заполняет tools/make_site.py прямо из строк @export в скриптах скинов — добавьте регулятор или поменяйте значение по умолчанию, и таблица поедет следом. Используйте эти имена под skin.dials в JSON. Регулятор, чьё значение по умолчанию записано как 14, — целое число, а записанное как 10.0 — число с плавающей точкой; пишите в JSON любую форму, сборщик приведёт её к типу скрипта. Default skin GoSkin — 17 Регулятор По умолчанию Что задаёт chip_fill_alpha 0.16 Непрозрачность заливки панели чипа. chip_edge_alpha 0.45 Непрозрачность грани панели чипа. alert_tint 0.1 Насколько сильно панель оповещения подкрашена в цвет своего состояния. slot_tint_lit 0.24 Акцентная подкраска панели быстрого слота, пока идёт его перезарядка. slot_tint_idle 0.08 Акцентная подкраска панели быстрого слота в покое. slot_border_lit 2 Ширина рамки быстрого слота (dp), пока идёт его перезарядка. slot_border_idle 1 Ширина рамки быстрого слота (dp) в покое. badge_pad_x 5 Внутренний отступ значка по горизонтали (dp) — количество, оставшееся время. badge_pad_y 1 Внутренний отступ значка по вертикали (dp). badge_edge_alpha 0.6 Непрозрачность грани панели значка. float_shadow_alpha 0.45 Непрозрачность тени плавающих карточек (обучающая подсказка, карточка вопроса). float_shadow_size 14 Размытие тени плавающих карточек (dp). float_shadow_lift 4 Смещение тени плавающей карточки вниз (dp). float_glow_size 10.0 Дальность свечения (dp) плавающей панели, которая светится вместо того, чтобы отбрасывать тень, — как панель со срезанными углами в sci-fi. joystick_base_alpha 0.42 Непрозрачность базового диска стика. joystick_ring_alpha 0.45 Непрозрачность кольца стика. joystick_ring_width 2.0 Ширина кольца стика (dp). Sci-fi skin GoSkinSciFi — 10 Регулятор По умолчанию Что задаёт cut_chip 7.0 Размер фаски (dp) у панели чипа. cut_skeleton 5.0 Размер фаски (dp) у панели-скелетона. cut_alert 8.0 Размер фаски (dp) у блока оповещения. cut_segment 8.0 Размер фаски (dp) у сегментированного переключателя. cut_slot 6.0 Размер фаски (dp) у панели быстрого слота. cut_disc_ratio 0.24 Фаска аватаров и дисков = диаметр × это отношение. slot_glow_alpha 0.45 Непрозрачность свечения слота, у которого идёт перезарядка. slot_glow_size 6.0 Дальность свечения (dp) слота, у которого идёт перезарядка. bracket_arm 12.0 Длина плеча (dp) прицельной скобки обучающей подсказки. bracket_thickness 2.0 Толщина линии (dp) прицельной скобки обучающей подсказки. Medieval skin GoSkinMedieval — 5 Регулятор По умолчанию Что задаёт slot_radius 4.0 Радиус угла (dp) средневековой рамки быстрого слота. leather_grain_alpha 0.035 Непрозрачность едва заметной кожаной фактуры внутри быстрых слотов. ornament_scale 1.0 Масштаб металлических украшений по углам быстрых слотов. Рамки меню используют shape.ornament_scale. bevel_strength 0.18 Сила металлического блика вдоль граней быстрого слота. slot_rivets 1 Показывать ли маленькие металлические заклёпки на быстрых слотах: 0 — скрыть, 1 — показать.","",-1],[17,"subclass-the-skin-optional","Наследовать скин (по желанию)",1,"В скине живёт только то, до чего не дотягиваются тема и форма, — шестиугольник стика, значки слотов, прицельная скобка обучающей подсказки. Наследуйте GoSkin, переопределите лишь эти методы и укажите в JSON на этот ресурс через skin. Теме, меняющей только цвет, этот шаг не нужен. Обещание держит проверка. tools/check_scaffold.sh при каждом запуске создаёт одноразовую тему — меняет акцент, ставит радиус 4 — и убеждается в успешной генерации, распространении токенов и чистом проходе по контрасту, после чего удаляет её. Первый же запуск обнаружил, что тема, в которой изменён только акцент, проваливает 8 пар: сборщик подтягивал цвета текста, но брал акцент как написано. Теперь он подтягивает и акцент, и подпись на нём.","",-1],[18,"same-hue-text-on-a-same-hue-tint","Текст одного тона на подкраске того же тона",1,"Эта ловушка встретилась в этой кодовой базе трижды — нажатые кнопки (акцентная панель, акцентная подпись), кнопки опасных действий и чипы. В палитре это выглядит хорошо и разваливается в тот же миг, когда его измеряют, потому что оба цвета делят один тон и потому не различаются по светлоте. Поэтому цвета подписей не выбираются вручную. И сборщик тем, и GoSkin подтягивают светлоту — и только светлоту — пока порог не будет пройден на той панели, на которой текст действительно лежит. Тон и насыщенность при этом уцелевают, так что палитра сохраняет характер, а её изменение сохраняет контраст.","",-1],[18,"colour-read-as-text-and-colour-painted-as-area-w","Цвет, читаемый как текст, и цвет, залитый как площадь, хотят противоположного",1,"В светлой теме предупреждающий цвет вынужден темнеть, чтобы оставаться читаемым как текст (#96500A). Когда заливка полосы наследует это, полоса опыта становится коричневой. Одним цветом дело не поправить: жёлтый ярок сам по себе, поэтому он берёт 3:1 вообще без серого жёлоба, а затемнение жёлоба делает только хуже (1.52 → 1.06). Поэтому эти две роли разделены. Цвет остаётся сочным — палитра несёт цвета только для заливки, такие как warning_vivid. Контраст берёт на себя грань — GoSkin рисует обводку в 1dp на любой заливке, которая не добирает 3:1 к своему жёлобу, так что «насколько она полна» остаётся читаемым. О пропуске сообщается. Без *_vivid заливка, вышедшая тёмной, заставляет сборщик напечатать the bar looks drab — add warning_vivid to the palette (по-корейски: «полоса тусклая — добавьте warning_vivid в палитру»). Место, которое раньше портилось молча, теперь говорит об этом.","MY_LIGHT = dict( warning=hexc(\"9A5407\"), # читается как текст warning_vivid=hexc(\"F2A007\"), # заливается на полосе )",-1],[18,"a-floating-panel-cannot-know-what-is-behind-it","Плавающая панель не может знать, что у неё за спиной",1,"HUD рисуется поверх игры — снежного поля или пещеры. Если его панель полупрозрачна, то всё, что позади, просвечивает и меняет цвет панели, утягивая за собой контраст текста. При 82% непрозрачности приглушённый текст тёмных тем падал до 3.74:1 на ярком фоне — ниже минимума. Поэтому полупрозрачные панели измеряют на чисто белом и чисто чёрном фоне; ничего хуже игровая сцена предложить не может. Панель HUD во встроенных темах непрозрачна ровно настолько, чтобы проходить проверку (92%), и при этом сохраняет стеклянный вид. По той же причине не фиксируются и цвета иконок. Глиф быстрого слота был жёстко задан белым и намерял 1.11:1 в светлой теме — теперь он следует за панелью, на которой лежит, ровно как и подписи. Две проверки, два охвата. check_contrast.py читает файлы тем; цвета, которые скин смешивает во время работы (чипы, слоты), измеряет раздел skin contrast набора тестов внутри Godot.","",-1]]};
